# -*- coding: utf-8 -*-
P1 = "Cari kalimat yang menyatakan pendapat/alasan penulis (〜からだ、〜と思う、しかし〜)."
P2 = "Cocokkan setiap pilihan dengan teks; pilihan yang menambahkan hal yang tidak ada di teks adalah salah."
JN = 'Teks menengah (内容理解・中文)'
W = ['Tidak disebut dalam teks.', 'Tidak sesuai dengan isi teks.', 'Bertentangan dengan isi teks.']
def Cc(jp, idt, qs): return dict(slot='chu', jenis=JN, jp=jp, id=idt, qs=qs)
def Q(q, opts, ans, alasan, bukti, wrong=W, poin=P1): return (q, opts, ans, alasan, bukti, wrong, poin)
B = [
 Cc('私は去年から、近所の公園で朝のジョギングを始めた。最初は五分走っただけで息が苦しくなったが、毎日少しずつ時間を伸ばしていくうちに、今では三十分走れるようになった。\n走り始めてから、夜よく眠れるようになり、仕事中の集中力も上がった気がする。今度は、地域のマラソン大会に出てみたいと思っている。',
    'Sejak tahun lalu saya mulai jogging pagi di taman dekat rumah. Awalnya lari lima menit saja napas sesak, tapi dengan menambah waktu sedikit demi sedikit, kini bisa lari 30 menit. Sejak mulai lari, tidur malam nyenyak dan konsentrasi kerja terasa naik. Berikutnya saya ingin ikut lomba maraton daerah.',
    [Q('「私」はジョギングを続けて、どう変わったか。',['夜よく眠れるようになり、仕事の集中力も上がった','走るのが嫌いになった','体重が増えた','仕事が忙しくなった'],0,'Tidur nyenyak dan fokus naik.','夜よく眠れるようになり、仕事中の集中力も上がった気がする'),
     Q('「私」はこれからどうしたいと思っているか。',['地域のマラソン大会に出たい','ジョギングをやめたい','夜に走りたい','会社を休みたい'],0,'Ingin ikut maraton.','地域のマラソン大会に出てみたい',W,P2)]),
 Cc('この町には、昔から続く「たこ焼き」の店がある。店主は七十歳のおじいさんで、毎日同じ場所で、同じ味のたこ焼きを焼き続けている。\n私は小学生のころから通っていて、大人になった今も、友達と一緒に食べに行く。店主は「味を変えないのが、一番難しい」と話していた。そのことばを聞いて、長く続ける大変さを知った。',
    'Di kota ini ada toko takoyaki yang berlangsung sejak lama. Pemiliknya kakek 70 tahun yang tiap hari di tempat sama memanggang takoyaki dengan rasa sama. Saya langganan sejak SD, dan sampai dewasa pun makan bersama teman. Pemilik berkata, "Tidak mengubah rasa adalah yang tersulit." Mendengar itu, saya paham beratnya bertahan lama.',
    [Q('店主が「一番難しい」と言ったことは何か。',['味を変えないこと','店を大きくすること','客を増やすこと','安く売ること'],0,'Tidak mengubah rasa.','「味を変えないのが、一番難しい」'),
     Q('「私」について正しいものはどれか。',['子どものころからこの店に通っている','最近この町に来た','店主の家族だ','たこ焼きを作っている'],0,'Langganan sejak SD.','小学生のころから通っていて',W,P2)]),
 Cc('先月、友達の結婚式に出席した。会場は海の見える小さな教会で、新郎新婦が誓いの言葉を述べるとき、私も思わず涙が出た。\n披露宴では、二人の子どものころの写真が紹介され、会場は笑いに包まれた。幸せそうな二人を見て、私も自分の大切な人を大事にしようと思った。',
    'Bulan lalu saya menghadiri pernikahan teman. Tempatnya gereja kecil menghadap laut; saat pengantin mengucapkan janji, saya pun refleks menangis. Di resepsi, foto masa kecil keduanya ditampilkan, dan ruangan dipenuhi tawa. Melihat pasangan bahagia itu, saya berpikir untuk menghargai orang tersayang.',
    [Q('「私」はなぜ涙が出たのか。',['新郎新婦が誓いの言葉を述べたから','料理がおいしかったから','写真が悲しかったから','友達が来なかったから'],0,'Saat janji pengantin.','誓いの言葉を述べるとき、私も思わず涙が出た'),
     Q('結婚式のあと、「私」はどう思ったか。',['大切な人を大事にしようと思った','自分も結婚しようと決めた','式に出て疲れた','もう行きたくない'],0,'Ingin menghargai orang tersayang.','自分の大切な人を大事にしようと思った',W,P2)]),
 Cc('日本の会社では、新入社員が最初の数か月、先輩について仕事を学ぶ制度がある。「OJT」と呼ばれ、実際の仕事をしながら覚えていく方法だ。\n良い点は、教科書では学べない現場の知識が身につくことだ。一方、先輩によって教え方に差があり、新人が不安になることもある。そのため、会社の中には、教える内容を決めておくところも増えている。',
    'Di perusahaan Jepang ada sistem karyawan baru belajar dari senior selama beberapa bulan pertama. Disebut OJT, yaitu belajar sambil mengerjakan pekerjaan nyata. Kelebihannya, mendapat pengetahuan lapangan yang tak bisa dipelajari dari buku. Sisi lain, cara mengajar berbeda tiap senior sehingga karyawan baru bisa cemas. Karena itu makin banyak perusahaan yang menentukan materi ajar.',
    [Q('OJTの良い点は何か。',['教科書では学べない現場の知識が身につく','給料が上がる','先輩が楽になる','仕事をしなくていい'],0,'Dapat pengetahuan lapangan.','教科書では学べない現場の知識が身につく'),
     Q('会社が教える内容を決めるのはなぜか。',['先輩によって教え方に差があり、新人が不安になるから','新人が多すぎるから','教科書がなくなったから','先輩がいなくなったから'],0,'Cara ajar senior berbeda.','先輩によって教え方に差があり、新人が不安になることもある。そのため',W,P2)]),
 Cc('私の祖父は、毎朝庭の花に水をやるのが日課だ。庭には、四季ごとにちがう花が咲いて、通りかかる人がよく足を止めて見ていく。\n先日、近所の女の子が「きれいですね」と声をかけてくれた。祖父はとてもうれしそうで、その日、その子に一輪の花をあげていた。小さな交流だが、祖父の笑顔を見て、私も幸せな気持ちになった。',
    'Kakek saya rutin menyiram bunga di kebun tiap pagi. Di kebun, bunga berbeda mekar tiap musim dan orang lewat sering berhenti melihat. Beberapa hari lalu, seorang gadis tetangga menyapa "Indah ya." Kakek sangat senang dan memberi anak itu setangkai bunga. Interaksi kecil, tapi melihat senyum kakek saya pun bahagia.',
    [Q('祖父の日課は何か。',['毎朝庭の花に水をやること','毎朝散歩に行くこと','毎朝花を売ること','毎朝新聞を読むこと'],0,'Menyiram bunga tiap pagi.','毎朝庭の花に水をやるのが日課だ'),
     Q('祖父は女の子に何をしたか。',['一輪の花をあげた','庭に入れなかった','お金をあげた','何も言わなかった'],0,'Memberi setangkai bunga.','その子に一輪の花をあげていた',W,P2)]),
 Cc('最近、「サブスク」と呼ばれる、月々お金を払って使い放題になるサービスが増えている。音楽や映画だけでなく、洋服や食事のサービスもある。\n便利な反面、使っていないサービスの料金を払い続けてしまう人も少なくない。契約するときは、本当に使うかどうかを考え、定期的に見直したほうがいいだろう。',
    'Belakangan layanan "sabuk" (langganan) yang membayar bulanan lalu pakai sepuasnya bertambah. Bukan hanya musik dan film, ada pula layanan pakaian dan makanan. Di sisi praktis, tak sedikit orang tetap membayar layanan yang tak dipakai. Saat berlangganan, pikirkan benar-benar akan dipakai atau tidak dan evaluasi berkala.',
    [Q('サブスクの問題点は何か。',['使っていないサービスの料金を払い続けてしまうこと','料金が毎回変わること','使える時間が決まっていること','会員が少ないこと'],0,'Membayar layanan tak dipakai.','使っていないサービスの料金を払い続けてしまう人も少なくない'),
     Q('契約するとき、筆者は何をすすめているか。',['本当に使うか考え、定期的に見直すこと','できるだけ多く契約すること','友達に決めてもらうこと','契約しないこと'],0,'Pikirkan dan evaluasi berkala.','本当に使うかどうかを考え、定期的に見直したほうがいい',W,P2)]),
 Cc('日本では、お正月に「初詣」に行く習慣がある。神社やお寺に行って、一年の健康や幸せをお祈りするのだ。\n私の家では、毎年元日の夜に家族で近くの神社へ行く。夜でも多くの人が並んでいて、寒いが、おみくじを引くのが楽しみだ。今年は「中吉」で、少し残念だったが、母は「努力すれば大丈夫」と笑っていた。',
    'Di Jepang ada kebiasaan "hatsumoude" saat tahun baru. Pergi ke kuil/vihara berdoa untuk kesehatan dan kebahagiaan setahun. Keluarga saya tiap malam 1 Januari pergi ke kuil dekat rumah. Meski malam, banyak orang antre dan dingin, tapi menarik omikuji jadi hal yang dinanti. Tahun ini dapat "chuukichi", sedikit kecewa, tapi ibu tertawa "kalau berusaha, tak masalah".',
    [Q('初詣とは何か。',['お正月に神社やお寺へ行ってお祈りすること','お正月に旅行すること','お正月に勉強すること','お正月にごちそうを食べること'],0,'Berdoa di kuil saat tahun baru.','神社やお寺に行って、一年の健康や幸せをお祈りする'),
     Q('今年のおみくじについて、正しいものはどれか。',['「中吉」で少し残念だった','「大吉」でうれしかった','引かなかった','母だけが引いた'],0,'Dapat chuukichi, agak kecewa.','今年は「中吉」で、少し残念だった',W,P2)]),
 Cc('駅の近くの古いビルが壊されることになった。このビルには、四十年以上、小さな書店が入っていて、地域の人に愛されていた。\n店主は「閉めるのはさびしいが、新しい場所でまた店を開く」と話している。私も何度も本を買いに行った場所なので、なくなるのは残念だが、店が続くと聞いて安心した。新しい店ができたら、また通いたい。',
    'Gedung tua dekat stasiun akan dirobohkan. Di gedung ini toko buku kecil berdiri lebih dari 40 tahun dan disayangi warga. Pemilik berkata, "Menutupnya sedih, tapi akan buka lagi di tempat baru." Saya pun sering membeli buku di sana, jadi sayang bila hilang, tapi lega mendengar toko akan lanjut. Kalau toko baru dibuka, saya ingin langganan lagi.',
    [Q('書店の店主はどうすると言っているか。',['新しい場所でまた店を開く','店を完全にやめる','店を売る','ビルを買う'],0,'Buka lagi di tempat baru.','新しい場所でまた店を開く'),
     Q('「私」は店が続くと聞いてどう思ったか。',['安心した','怒った','悲しくなった','関心がなかった'],0,'Lega.','店が続くと聞いて安心した',W,P2)]),
 Cc('私の姉は看護師で、病院で働いている。夜勤もあって大変そうだが、「患者さんが元気になって退院していく姿を見るのが、一番うれしい」と言っている。\n先日、姉が久しぶりに休みをとって、家族で食事に行った。姉は疲れているはずなのに、よく笑って、おいしそうに食べていた。私は、姉の仕事に誇りを持っている。',
    'Kakak perempuan saya perawat, bekerja di rumah sakit. Ada shift malam yang tampak berat, tetapi katanya "melihat pasien sehat lalu keluar rumah sakit adalah yang paling membahagiakan". Beberapa hari lalu kakak mengambil libur setelah lama dan kami makan bersama keluarga. Meski seharusnya lelah, kakak banyak tertawa dan makan dengan lahap. Saya bangga pada pekerjaan kakak.',
    [Q('姉が一番うれしいと言っているのはどんなときか。',['患者さんが元気になって退院するとき','給料をもらうとき','休みをとるとき','夜勤が終わるとき'],0,'Saat pasien pulang sehat.','患者さんが元気になって退院していく姿を見るのが、一番うれしい'),
     Q('食事のときの姉の様子はどうだったか。',['疲れているはずなのによく笑っていた','ずっと黙っていた','食べなかった','すぐ帰った'],0,'Banyak tertawa.','よく笑って、おいしそうに食べていた',W,P2)]),
 Cc('最近の若い人は、本を読まなくなったと言われる。しかし、私が通う大学の図書館は、いつも学生でいっぱいだ。\n聞いてみると、本を借りるためではなく、静かな場所で勉強したり、友達と課題をしたりするために来る学生が多い。図書館の役割が、本を借りる場所から、勉強する場所へと変わってきているのかもしれない。',
    'Dikatakan anak muda sekarang tak lagi membaca buku. Namun perpustakaan kampus saya selalu penuh mahasiswa. Setelah ditanya, banyak yang datang bukan untuk meminjam buku, melainkan belajar di tempat tenang atau mengerjakan tugas bersama teman. Mungkin peran perpustakaan berubah dari tempat meminjam buku menjadi tempat belajar.',
    [Q('図書館に来る学生の多くは、何のために来るのか。',['静かな場所で勉強したり、課題をしたりするため','本を借りるため','寝るため','友達と遊ぶため'],0,'Belajar & mengerjakan tugas.','静かな場所で勉強したり、友達と課題をしたりするために来る'),
     Q('筆者は、図書館の役割をどう考えているか。',['本を借りる場所から勉強する場所へ変わってきている','本を借りる場所に戻る','なくなる','変わっていない'],0,'Beralih jadi tempat belajar.','本を借りる場所から、勉強する場所へと変わってきているのかもしれない',W,P2)]),
 Cc('日本では、小学生の登校時間になると、「見守り隊」のボランティアが通学路に立っている。多くは地域の高齢者で、子どもたちに「おはよう」と声をかけながら、車の安全を確認している。\n子どもたちも、見守り隊の人たちを知っていて、道で会うと自分から挨拶する。こうして、地域の大人と子どもの間に、自然な交流が生まれている。',
    'Di Jepang, saat jam berangkat sekolah SD, sukarelawan "pengawal" berdiri di jalan sekolah. Kebanyakan lansia setempat, menyapa anak "selamat pagi" sambil memastikan keselamatan dari kendaraan. Anak-anak juga mengenal mereka dan menyapa duluan jika bertemu di jalan. Dengan begitu, tercipta interaksi alami antara orang dewasa dan anak di lingkungan.',
    [Q('見守り隊の人たちは、何をしているか。',['子どもに声をかけ、車の安全を確認している','子どもに勉強を教えている','車を運転している','学校の掃除をしている'],0,'Menyapa dan menjaga keselamatan.','声をかけながら、車の安全を確認している'),
     Q('この活動からどんな良いことが生まれているか。',['大人と子どもの自然な交流','学校の成績の向上','道路の工事','お金の節約'],0,'Interaksi alami.','地域の大人と子どもの間に、自然な交流が生まれている',W,P2)]),
 Cc('私は先月、初めて自分で料理教室に通い始めた。これまでは、レシピを見ながら作るだけで、なぜその手順なのかを考えたことがなかった。\n教室では、先生が「野菜を切る大きさで、火が通る時間が変わる」と教えてくれた。理由を知ると、作るのがもっと楽しくなり、家でも工夫するようになった。知識が料理を楽しくするのだと感じた。',
    'Bulan lalu saya pertama kali ikut kelas memasak. Dulu saya hanya mengikuti resep tanpa memikirkan alasan urutannya. Di kelas guru mengajarkan "ukuran potongan sayur mengubah waktu matang". Setelah paham alasannya, memasak makin menyenangkan dan di rumah pun saya berkreasi. Saya merasa pengetahuan membuat memasak menyenangkan.',
    [Q('これまで「私」は料理をするとき、どうしていたか。',['レシピを見ながら作るだけで、理由は考えなかった','自分で工夫していた','先生に習っていた','料理をしなかった'],0,'Hanya mengikuti resep.','レシピを見ながら作るだけで、なぜその手順なのかを考えたことがなかった'),
     Q('料理教室に通って、「私」はどう変わったか。',['理由を知って、家でも工夫するようになった','料理がきらいになった','レシピが読めなくなった','外食が増えた'],0,'Berkreasi di rumah.','理由を知ると、作るのがもっと楽しくなり、家でも工夫するようになった',W,P2)]),
 Cc('今、日本では「リモートワーク」を取り入れる会社が増えている。家で仕事ができるので、通勤の時間が節約でき、育児や介護をしながら働く人にも便利だ。\nしかし、同僚と直接話す機会が減り、孤独を感じる人もいる。そこで、週に一度だけ出社する日を決めて、顔を合わせる会社もある。働き方を選べる時代になったが、人とのつながりも大切にしたい。',
    'Kini di Jepang makin banyak perusahaan menerapkan kerja jarak jauh. Karena bisa kerja di rumah, waktu perjalanan hemat dan praktis bagi yang sambil mengasuh/merawat. Namun kesempatan bicara langsung dengan rekan berkurang dan ada yang merasa kesepian. Karena itu ada perusahaan yang menetapkan satu hari per pekan masuk kantor untuk bertemu. Zaman bisa memilih cara kerja, tapi kita ingin menjaga hubungan antarmanusia.',
    [Q('リモートワークの良い点は何か。',['通勤の時間が節約でき、育児や介護をしながら働きやすい','同僚とよく話せる','給料が上がる','仕事が減る'],0,'Hemat waktu dan fleksibel.','通勤の時間が節約でき、育児や介護をしながら働く人にも便利'),
     Q('孤独を感じる人への対策として、どんな会社があるか。',['週に一度だけ出社する日を決める会社','リモートワークをやめる会社','給料を上げる会社','全員を解雇する会社'],0,'Satu hari masuk kantor.','週に一度だけ出社する日を決めて、顔を合わせる会社もある',W,P2)]),
 Cc('夏になると、日本では各地で花火大会が開かれる。大きな音と美しい光で、多くの人が楽しみにしている。\n私の町の花火大会は、浴衣を着て参加する人が多い。去年は初めて友達と浴衣を着て行った。歩きにくかったが、写真をたくさん撮って、いい思い出になった。人混みは大変だったが、また行きたいと思っている。',
    'Saat musim panas, festival kembang api digelar di berbagai tempat di Jepang. Dengan suara besar dan cahaya indah, banyak orang menantikannya. Di festival kota saya banyak yang memakai yukata. Tahun lalu untuk pertama kali saya memakai yukata bersama teman. Sulit berjalan, tapi banyak foto dan jadi kenangan. Meski kerumunan merepotkan, saya ingin pergi lagi.',
    [Q('「私」は去年の花火大会でどうしたか。',['友達と浴衣を着て行った','一人で行った','行かなかった','家で見た'],0,'Memakai yukata dengan teman.','去年は初めて友達と浴衣を着て行った'),
     Q('「私」は花火大会についてどう思っているか。',['人混みは大変だったがまた行きたい','もう行きたくない','浴衣が楽だった','写真は撮らなかった'],0,'Ingin pergi lagi.','人混みは大変だったが、また行きたいと思っている',W,P2)]),
 Cc('私の住むアパートでは、ごみの出し方で住民の間にトラブルがあった。決められた日以外にごみを出す人がいて、においや虫が問題になったのだ。\n管理人は、ごみ置き場の前に大きな張り紙を貼り、出す日と分け方をわかりやすく書いた。すると、守る人が増え、問題は少しずつ減った。ルールは、わかりやすく伝えることが大切だと感じた。',
    'Di apartemen saya terjadi masalah antarwarga soal cara membuang sampah. Ada yang membuang di luar hari yang ditentukan sehingga bau dan serangga jadi masalah. Pengelola menempel pengumuman besar di depan tempat sampah, menulis hari dan cara memilah dengan jelas. Lalu yang mematuhi bertambah dan masalah perlahan berkurang. Saya merasa aturan penting disampaikan dengan jelas.',
    [Q('アパートで問題になったことは何か。',['決められた日以外にごみを出す人がいて、においや虫が出たこと','騒音がひどかったこと','家賃が上がったこと','管理人がいないこと'],0,'Buang sampah di luar hari.','決められた日以外にごみを出す人がいて、においや虫が問題になった'),
     Q('管理人が張り紙をしたあと、どうなったか。',['守る人が増え、問題が減った','問題が増えた','張り紙が取られた','管理人が辞めた'],0,'Yang patuh bertambah.','守る人が増え、問題は少しずつ減った',W,P2)]),
 Cc('私は子どものころ、野菜が大嫌いだった。特にピーマンは、においを嗅ぐだけで食べられなかった。ところが、大学生になって一人暮らしを始め、自分で料理をするようになってから、少しずつ食べられるようになった。\n自分で味つけを工夫できるのが大きい。今では、ピーマンの肉詰めが得意料理になった。人の好みは、変わるものだと思う。',
    'Waktu kecil saya sangat benci sayur. Terutama paprika hijau, mencium baunya saja tak bisa dimakan. Namun saat kuliah dan mulai hidup sendiri serta memasak sendiri, perlahan jadi bisa makan. Bisa mengatur bumbu sendiri itu penting. Kini paprika isi daging jadi masakan andalan. Saya rasa selera orang bisa berubah.',
    [Q('「私」が野菜を食べられるようになったきっかけは何か。',['一人暮らしを始めて自分で料理をするようになったこと','母に叱られたこと','学校の給食','友達にすすめられたこと'],0,'Mulai memasak sendiri.','一人暮らしを始め、自分で料理をするようになってから'),
     Q('「私」の得意料理は何か。',['ピーマンの肉詰め','野菜サラダ','カレー','ラーメン'],0,'Paprika isi daging.','ピーマンの肉詰めが得意料理になった',W,P2)]),
 Cc('日本の郵便局では、手紙や荷物を送るだけでなく、銀行や保険のサービスもしている。特に、地方の小さな町では、郵便局が銀行の代わりになっていることが多い。\n町に銀行がない場合、お年寄りは郵便局でお金を出したり、預けたりできる。そのため、郵便局は地域の暮らしを支える大切な場所になっている。',
    'Kantor pos Jepang selain mengirim surat dan paket juga menyediakan layanan bank dan asuransi. Khususnya di kota kecil daerah, kantor pos sering menggantikan bank. Jika tak ada bank di kota, lansia bisa menarik dan menyimpan uang di kantor pos. Karena itu kantor pos menjadi tempat penting penopang kehidupan daerah.',
    [Q('地方の小さな町で、郵便局が果たしている役割は何か。',['銀行の代わりになること','学校の代わりになること','病院の代わりになること','市役所の代わりになること'],0,'Menggantikan bank.','郵便局が銀行の代わりになっていることが多い'),
     Q('お年寄りは郵便局で何ができるか。',['お金を出したり預けたりできる','薬を買える','電車に乗れる','本を借りられる'],0,'Menarik dan menyimpan uang.','お金を出したり、預けたりできる',W,P2)]),
 Cc('私のクラスでは、毎日一人ずつ、朝の「一分間スピーチ」をする。テーマは自由で、好きな食べ物や休みの日の過ごし方など、何でもいい。\n最初は、人前で話すのが恥ずかしかったが、毎日聞いているうちに、友達のことがよくわかるようになった。クラスの雰囲気も明るくなった気がする。小さな習慣でも、続けると大きな効果があると思う。',
    'Di kelas saya, tiap hari satu orang melakukan "pidato satu menit" pagi hari. Temanya bebas, makanan favorit atau cara menghabiskan hari libur, apa saja. Awalnya malu bicara di depan, tetapi karena tiap hari mendengar, saya jadi memahami teman. Suasana kelas pun terasa lebih ceria. Hal kecil jika terus dilakukan berefek besar.',
    [Q('「一分間スピーチ」のテーマはどうなっているか。',['自由で何でもいい','先生が決める','天気だけ','勉強のことだけ'],0,'Bebas.','テーマは自由で…何でもいい'),
     Q('スピーチを続けて、クラスはどう変わったか。',['友達のことがよくわかり、雰囲気が明るくなった','成績が全員上がった','話す人がいなくなった','スピーチが嫌いになった'],0,'Saling memahami, ceria.','友達のことがよくわかるようになった。クラスの雰囲気も明るくなった気がする',W,P2)]),
]
